(4465985, 642666, 26001, '<td valign="top">very similar images have been on the podium in two previous advertisement challenges, so i dont know whether i can vote for this image purely based on its quality (which i consider is good btw). hence, i will just praise this shot here but will not vote :)</td>', 'very similar images have been on the podium in two previous advertisement challenges, so i dont know whether i can vote for this image purely based on its quality (which i consider is good btw). hence, i will just praise this shot here but will not vote :)', '2008-02-06 19:30:28.000000', NULL, 1),
(4465994, 642487, 33672, '<td valign="top">A funny play on the theme description. Original way to add text to the phot in basic.</td>', 'A funny play on the theme description. Original way to add text to the phot in basic.', '2008-02-06 19:32:44.000000', NULL, 1),
(4466000, 642425, 33672, '<td valign="top">I guess I see what your going for here but I don''t know if its effective. Without the title I''d have no clue what the product is.</td>', 'I guess I see what your going for here but I don''t know if its effective. Without the title I''d have no clue what the product is.', '2008-02-06 19:34:22.000000', NULL, 1),
(4466008, 643019, 33672, '<td valign="top">Nice lighting and comp. Text could be easily placed. Personally, I''d ask for a deeper DOF to highlight the product better.</td>', 'Nice lighting and comp. Text could be easily placed. Personally, I''d ask for a deeper DOF to highlight the product better.', '2008-02-06 19:36:07.000000', NULL, 1),
(4466014, 642940, 33672, '<td valign="top">Perfect ad photo. Comp lends to easy text placement. Product is clear and prominant. Nice contrast and tones.</td>', 'Perfect ad photo. Comp lends to easy text placement. Product is clear and prominant. Nice contrast and tones.', '2008-02-06 19:37:24.000000', NULL, 1),
(4466024, 642813, 33672, '<td valign="top">Nice comp and lighting. Ad could have text added very easily. A little less reflection would be my only suggestion. Perhaps by adding a photo filter in PP.</td>', 'Nice comp and lighting. Ad could have text added very easily. A little less reflection would be my only suggestion. Perhaps by adding a photo filter in PP.', '2008-02-06 19:39:58.000000', NULL, 1),
(4466029, 643157, 33672, '<td valign="top">Nice photo that needs no text to tell what the product is. Clever title and set up makes this a very good ad.</td>', 'Nice photo that needs no text to tell what the product is. Clever title and set up makes this a very good ad.', '2008-02-06 19:41:00.000000', NULL, 1),
