(4467531, 641356, 70689, '<td valign="top">The picture is unlevel, not very sharp and the sky is severely overprocessed. Sorry to have to put it this way, but this is not the way to sell a house. 3</td>', 'The picture is unlevel, not very sharp and the sky is severely overprocessed. Sorry to have to put it this way, but this is not the way to sell a house. 3', '2008-02-07 08:09:49.000000', NULL, 1),
(4467532, 640327, 70689, '<td valign="top">exactly what is this an ad for?</td>', 'exactly what is this an ad for?', '2008-02-07 08:10:28.000000', NULL, 1),
(4467534, 642789, 70689, '<td valign="top">could have just more depth of field</td>', 'could have just more depth of field', '2008-02-07 08:10:59.000000', NULL, 1),
(4467537, 641694, 70689, '<td valign="top">The fact that the angle is slightly different than that from the bottle works very well here. 7</td>', 'The fact that the angle is slightly different than that from the bottle works very well here. 7', '2008-02-07 08:14:27.000000', NULL, 1),
(4467540, 642995, 70689, '<td valign="top">It''s a bit dark, causing you to loose detail. Yes, my monitor is callibrated.</td>', 'It''s a bit dark, causing you to loose detail. Yes, my monitor is callibrated.', '2008-02-07 08:15:57.000000', NULL, 1),
(4467542, 642873, 70689, '<td valign="top">The idea is nice, but the harsh lighting causes ugly shadows. On top of that, your backdrop needs ironing. 3</td>', 'The idea is nice, but the harsh lighting causes ugly shadows. On top of that, your backdrop needs ironing. 3', '2008-02-07 08:17:11.000000', NULL, 1),
(4467545, 643137, 70689, '<td valign="top">Made me smile. Well executed too 8</td>', 'Made me smile. Well executed too 8', '2008-02-07 08:17:49.000000', NULL, 1),
(4467548, 641478, 70689, '<td valign="top">Had to think about it. And that often means a low score from speed voters who do not take the time to think. 6</td>', 'Had to think about it. And that often means a low score from speed voters who do not take the time to think. 6', '2008-02-07 08:19:09.000000', NULL, 1),
(4467550, 641885, 70689, '<td valign="top">That''s not a hip :0 ;) 6</td>', 'That''s not a hip :0 ;) 6', '2008-02-07 08:19:55.000000', NULL, 1),
(4467553, 641056, 70689, '<td valign="top">like it. 8</td>', 'like it. 8', '2008-02-07 08:20:33.000000', NULL, 1),
(4467555, 642962, 70689, '<td valign="top">Cool shot, very good execution. Me like 8</td>', 'Cool shot, very good execution. Me like 8', '2008-02-07 08:24:02.000000', NULL, 1),
(4467558, 642791, 70689, '<td valign="top">I think this picture is a bit flat, it has no depth. It has no apparant composition either, just three boxfronts in a row. Doesn''t work for me. 3</td>', 'I think this picture is a bit flat, it has no depth. It has no apparant composition either, just three boxfronts in a row. Doesn''t work for me. 3', '2008-02-07 08:26:17.000000', NULL, 1),
(4467600, 642962, 80326, '<td valign="top">Very nicely done. Clever. I''d prefer if the BG colour was a little more different to the colour of the tomato bottle though.</td>', 'Very nicely done. Clever. I''d prefer if the BG colour was a little more different to the colour of the tomato bottle though.', '2008-02-07 08:48:10.000000', NULL, 1),
(4467665, 643048, 84438, '<td valign="top">An excellent photograph.  Lighting is perfect, and nice job not blowing out the whites.<br/> <br/>The only thing that I find distracting about this photo is that the business card being advertised is so much smaller than the other cards.  This doesn''t make it stand out as much as it should.<br/> <br/>Other than that, this is great.</td>', 'An excellent photograph.  Lighting is perfect, and nice job not blowing out the whites. The only thing that I find distracting about this photo is that the business card being advertised is so much smaller than the other cards.  This doesn''t make it stand out as much as it should. Other than that, this is great.', '2008-02-07 09:20:47.000000', NULL, 1),
(4467672, 643006, 84438, '<td valign="top">What a great idea.  I really like the composition of this photo.  The bottle seems to lack a bit of sharpness or something..  I can''t put my finger on it, but something just feels ''off''.  An excellent job though.</td>', 'What a great idea.  I really like the composition of this photo.  The bottle seems to lack a bit of sharpness or something..  I can''t put my finger on it, but something just feels ''off''.  An excellent job though.', '2008-02-07 09:22:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4467673, 642574, 84438, '<td valign="top">Very nicely done.</td>', 'Very nicely done.', '2008-02-07 09:22:51.000000', NULL, 1),
(4467680, 642957, 84438, '<td valign="top">The (plexiglass) stand is a great addition to this photo.  Is there a bit of red creeping in to the top of the bag though?  Very nice overall.</td>', 'The (plexiglass) stand is a great addition to this photo.  Is there a bit of red creeping in to the top of the bag though?  Very nice overall.', '2008-02-07 09:24:00.000000', NULL, 1),
(4467682, 643173, 84438, '<td valign="top">Unfortunately I can''t really tell what this is, but it is a very effective photograph nonetheless.</td>', 'Unfortunately I can''t really tell what this is, but it is a very effective photograph nonetheless.', '2008-02-07 09:24:31.000000', NULL, 1),
(4467688, 642555, 84438, '<td valign="top">A really simple photograph, but excellent.  The lighting is fantastic, and the B&amp;W conversion is really nicely done.  Your levels look perfect.  Excellent details in the shoe as well.<br/> <br/>My only complaint would be that I wish there was a bit more light on the spikes..  It makes them very hard to see.  <br/> <br/>This is great though.</td>', 'A really simple photograph, but excellent.  The lighting is fantastic, and the B&W conversion is really nicely done.  Your levels look perfect.  Excellent details in the shoe as well. My only complaint would be that I wish there was a bit more light on the spikes..  It makes them very hard to see.   This is great though.', '2008-02-07 09:26:23.000000', NULL, 1),
(4467693, 642949, 84438, '<td valign="top">Really really nice.  It might even jump out more with more light on the gum.</td>', 'Really really nice.  It might even jump out more with more light on the gum.', '2008-02-07 09:27:14.000000', NULL, 1),
(4467699, 642995, 84438, '<td valign="top">Nice contrast, but it seems like the box and camera are a bit too dark..  They details are lost.  Very pleasing photograph though.</td>', 'Nice contrast, but it seems like the box and camera are a bit too dark..  They details are lost.  Very pleasing photograph though.', '2008-02-07 09:28:04.000000', NULL, 1),
(4467706, 642988, 84438, '<td valign="top">A really really good idea.  Because the bottle is such a major aspect of the shot, I feel that it would work better with a deeper DOF.  To be honest, I can''t even tell what the object is in front of the bottle.</td>', 'A really really good idea.  Because the bottle is such a major aspect of the shot, I feel that it would work better with a deeper DOF.  To be honest, I can''t even tell what the object is in front of the bottle.', '2008-02-07 09:29:44.000000', NULL, 1),
(4467709, 640470, 84438, '<td valign="top">A very pleasing shot.  I think it would be even more powerful if the colours of the candy were brought out even more.  The lighting is great though.</td>', 'A very pleasing shot.  I think it would be even more powerful if the colours of the candy were brought out even more.  The lighting is great though.', '2008-02-07 09:30:48.000000', NULL, 1),
(4467714, 642837, 84438, '<td valign="top">Your lighting and focus is spot on.  DOF is excellent.  Composition is great.  This is one of my favourites for sure.  <br/>8</td>', 'Your lighting and focus is spot on.  DOF is excellent.  Composition is great.  This is one of my favourites for sure.  8', '2008-02-07 09:32:11.000000', NULL, 1),
(4467721, 642804, 84438, '<td valign="top">Ha! Funny.  Took me a bit to even see the can in the photo though.  As an advertisement, it really needs to be immediately noticable.  The composition is nice, if a little uninteresting.  The lighting is ok, though the bottom sheets look pretty blown out.<br/>4</td>', 'Ha! Funny.  Took me a bit to even see the can in the photo though.  As an advertisement, it really needs to be immediately noticable.  The composition is nice, if a little uninteresting.  The lighting is ok, though the bottom sheets look pretty blown out.4', '2008-02-07 09:34:15.000000', NULL, 1),
(4467728, 642898, 84438, '<td valign="top">I like the composition and the DOF in this shot.  I realize that the dial and mouthpeice colour probably is cream coloured, but unfortunately it makes the shot look a little bland.  There''s something missing from this shot but I can''t quite put my figer on it.<br/>5</td>', 'I like the composition and the DOF in this shot.  I realize that the dial and mouthpeice colour probably is cream coloured, but unfortunately it makes the shot look a little bland.  There''s something missing from this shot but I can''t quite put my figer on it.5', '2008-02-07 09:35:57.000000', NULL, 1),
(4467731, 642701, 84438, '<td valign="top">Nice DOF and focus.  This is very well done, but a little bit cliche in my opinion.<br/>5</td>', 'Nice DOF and focus.  This is very well done, but a little bit cliche in my opinion.5', '2008-02-07 09:36:57.000000', NULL, 1),
(4467741, 642567, 84438, '<td valign="top">Your lighting is great in this shot.  Nice job keeping the shine off of the glass of milk.  A very nice photo.<br/> <br/>The shot looks a bit flat to me.  Are you right into the highlights on your histogram with this shot?<br/> <br/>6</td>', 'Your lighting is great in this shot.  Nice job keeping the shine off of the glass of milk.  A very nice photo. The shot looks a bit flat to me.  Are you right into the highlights on your histogram with this shot? 6', '2008-02-07 09:38:34.000000', NULL, 1),
(4467750, 641056, 84438, '<td valign="top">Very, very nice job.  Nice macro shot and your DOF could not be better.  Composition is excellent.  Some nit-pickers may mark you down for the slight tilt of the jeans, but I think it enhances this photo.<br/>8</td>', 'Very, very nice job.  Nice macro shot and your DOF could not be better.  Composition is excellent.  Some nit-pickers may mark you down for the slight tilt of the jeans, but I think it enhances this photo.8', '2008-02-07 09:40:20.000000', NULL, 1),
(4467755, 642521, 84438, '<td valign="top">I''ve done similiar shots, and I know how difficult it is to keep the shine off of the watch face.  Nicely done.</td>', 'I''ve done similiar shots, and I know how difficult it is to keep the shine off of the watch face.  Nicely done.', '2008-02-07 09:40:58.000000', NULL, 1),
(4467760, 641924, 84438, '<td valign="top">Hehe..  Funny!  Good lighting, if not a little too shadowy for my liking.<br/>5</td>', 'Hehe..  Funny!  Good lighting, if not a little too shadowy for my liking.5', '2008-02-07 09:41:30.000000', NULL, 1),
(4467770, 642997, 84438, '<td valign="top">I think you''re going to get a lot of similar comments on this photo.  An excellent idea, with some great aspects..  But the subject (the wrapper) is so dark!  What is the stuff around the wrapper?  I can''t even tell.<br/>4</td>', 'I think you''re going to get a lot of similar comments on this photo.  An excellent idea, with some great aspects..  But the subject (the wrapper) is so dark!  What is the stuff around the wrapper?  I can''t even tell.4', '2008-02-07 09:43:17.000000', NULL, 1),
(4467831, 641732, 84438, '<td valign="top">I do like a lot of aspects of this photograph, but I do have some issues with it.<br/>1) Lighting seems off.  No definition in the bottle, but the lighting is very harsh on the face of it.<br/>2) The ''splash'' is fairly cliche on this site.  It''s been perfected by many people.  This splash looks like it was taken with a shutter speed that is a bit too slow.  It''s quite blurry, which doesn''t seem to work as well.<br/> <br/>I apologize if this sounds too critical, but I do believe that there is a lot of potential in this shot.</td>', 'I do like a lot of aspects of this photograph, but I do have some issues with it.1) Lighting seems off.  No definition in the bottle, but the lighting is very harsh on the face of it.2) The ''splash'' is fairly cliche on this site.  It''s been perfected by many people.  This splash looks like it was taken with a shutter speed that is a bit too slow.  It''s quite blurry, which doesn''t seem to work as well. I apologize if this sounds too critical, but I do believe that there is a lot of potential in this shot.', '2008-02-07 09:59:53.000000', NULL, 1),
(4467839, 641664, 84438, '<td valign="top">Not sure what this is advertising.  Is ''memories'' the product?<br/> <br/>The lighting could definately be better in this photo.  Unfortunately, it looks like just a snapshot of pictures.</td>', 'Not sure what this is advertising.  Is ''memories'' the product? The lighting could definately be better in this photo.  Unfortunately, it looks like just a snapshot of pictures.', '2008-02-07 10:01:24.000000', NULL, 1),
(4467841, 642982, 84438, '<td valign="top">Very unique composition.  I like it.</td>', 'Very unique composition.  I like it.', '2008-02-07 10:01:51.000000', NULL, 1),
(4467843, 642541, 86447, '<td valign="top">Not being a theatre person, I really had to study to figure out what "Tage Blood" is.   *grin*   An unfortunate accident on the label.</td>', 'Not being a theatre person, I really had to study to figure out what "Tage Blood" is.   *grin*   An unfortunate accident on the label.', '2008-02-07 10:02:18.000000', NULL, 1),
(4467844, 643162, 86447, '<td valign="top">Great mood.</td>', 'Great mood.', '2008-02-07 10:02:28.000000', NULL, 1),
(4467850, 643156, 84438, '<td valign="top">A nice photo, but I think it would look better if the composition were different..  Where the subject was not centered in the shot.  Also, it would probably be more striking if the subject was not looking directly into the camera.<br/> <br/>Your B&amp;W conversion and levels are very, very well done.<br/>5</td>', 'A nice photo, but I think it would look better if the composition were different..  Where the subject was not centered in the shot.  Also, it would probably be more striking if the subject was not looking directly into the camera. Your B&W conversion and levels are very, very well done.5', '2008-02-07 10:03:20.000000', NULL, 1),
(4467851, 641334, 86447, '<td valign="top">The blown highlights on the name of the product''s name make this not so ''advertismenty''.</td>', 'The blown highlights on the name of the product''s name make this not so ''advertismenty''.', '2008-02-07 10:03:28.000000', NULL, 1),
(4467852, 642962, 32767, '<td valign="top">I''d say this is the blue ribbon right here but for such a slick concept, I think the lighting isn''t great. The left side is perfect but the right could use some more pop. The shadow, top right is a little too dark by contrast. I love the background color you chose. Cheers and good luck!</td>', 'I''d say this is the blue ribbon right here but for such a slick concept, I think the lighting isn''t great. The left side is perfect but the right could use some more pop. The shadow, top right is a little too dark by contrast. I love the background color you chose. Cheers and good luck!', '2008-02-07 10:03:52.000000', NULL, 1),
(4467854, 640408, 86447, '<td valign="top">I think less purple would make this a better advertisement.</td>', 'I think less purple would make this a better advertisement.', '2008-02-07 10:04:06.000000', NULL, 1),
(4467855, 642834, 84438, '<td valign="top">Hmmm...  I don''t understand the title, but I like a lot of aspects of this photo.  The reflection is nice, and it comes off as a unique shot.<br/>5</td>', 'Hmmm...  I don''t understand the title, but I like a lot of aspects of this photo.  The reflection is nice, and it comes off as a unique shot.5', '2008-02-07 10:04:23.000000', NULL, 1),
(4467856, 642665, 89431, '<td valign="top">Beatiful picture. I really like how the glass and... liquid? distorted the bottle. I also like how you used all the space in your photograph.</td>', 'Beatiful picture. I really like how the glass and... liquid? distorted the bottle. I also like how you used all the space in your photograph.', '2008-02-07 10:04:55.000000', NULL, 1),
(4467857, 641657, 86447, '<td valign="top">I think that at something should be in sharp focus to show what''s being advertised.</td>', 'I think that at something should be in sharp focus to show what''s being advertised.', '2008-02-07 10:05:05.000000', NULL, 1),
(4467866, 642873, 86447, '<td valign="top">The blue background does not compliment the product.  Perhaps a different color background and place the product further away... or decrease the DOF, so the creases are not so sharply seen in the blue material.  The drink does not have the freshly-poured look of Sprite with carbonation bubbles...   Just suggestions for making this a better ''advertisement''.  And only my opinion, of course.</td>', 'The blue background does not compliment the product.  Perhaps a different color background and place the product further away... or decrease the DOF, so the creases are not so sharply seen in the blue material.  The drink does not have the freshly-poured look of Sprite with carbonation bubbles...   Just suggestions for making this a better ''advertisement''.  And only my opinion, of course.', '2008-02-07 10:07:41.000000', NULL, 1),
(4467870, 642412, 86447, '<td valign="top">I wish the label were turned into the photo instead of out of it.  Drawing the eye into the image instead of on to the next page in the magazine this advertisement would be placed in.  The lighting is superb.</td>', 'I wish the label were turned into the photo instead of out of it.  Drawing the eye into the image instead of on to the next page in the magazine this advertisement would be placed in.  The lighting is superb.', '2008-02-07 10:09:10.000000', NULL, 1),
(4467872, 641658, 86447, '<td valign="top">I like the feel of this...  I wish the lighting on her face were a bit better to give us a clear subject to focus on before exploring the rest of the scene.</td>', 'I like the feel of this...  I wish the lighting on her face were a bit better to give us a clear subject to focus on before exploring the rest of the scene.', '2008-02-07 10:09:55.000000', NULL, 1),
(4467876, 641961, 89431, '<td valign="top">The fish in the back looks a little pixalated, it took me a while to  figure out what I was looking at. I do like the idea of this picture and the fact you let only the thing your advertising have bright colors, it really draws my eye to it.</td>', 'The fish in the back looks a little pixalated, it took me a while to  figure out what I was looking at. I do like the idea of this picture and the fact you let only the thing your advertising have bright colors, it really draws my eye to it.', '2008-02-07 10:10:14.000000', NULL, 1),
(4467883, 641241, 84438, '<td valign="top">Very nice!  Your lighting is good.  Your composition is very good.  Focus is excellent.  The darker background really sets your subject off.<br/>7</td>', 'Very nice!  Your lighting is good.  Your composition is very good.  Focus is excellent.  The darker background really sets your subject off.7', '2008-02-07 10:12:18.000000', NULL, 1),
(4467884, 642913, 86447, '<td valign="top">Perhaps a drop or two on the right side of this product would give this image something that makes us want to examine the image.  Make us think that someone thought it was good enough to drink...   The light is not as good as it could be... putting the top of the can in a bit too much darkness.  Only my opinion, of course.  The image is well focused with great DOF.</td>', 'Perhaps a drop or two on the right side of this product would give this image something that makes us want to examine the image.  Make us think that someone thought it was good enough to drink...   The light is not as good as it could be... putting the top of the can in a bit too much darkness.  Only my opinion, of course.  The image is well focused with great DOF.', '2008-02-07 10:12:21.000000', NULL, 1),
(4467888, 642715, 86447, '<td valign="top">The highly patterned cup, although beautiful, distracts from the product.</td>', 'The highly patterned cup, although beautiful, distracts from the product.', '2008-02-07 10:12:55.000000', NULL, 1),
(4467892, 642962, 86447, '<td valign="top">How in the world did you get that label on tomatoes without PS??  My only nitpick is that the lighting could be better on the right side.</td>', 'How in the world did you get that label on tomatoes without PS??  My only nitpick is that the lighting could be better on the right side.', '2008-02-07 10:14:04.000000', NULL, 1),
(4467894, 641673, 84438, '<td valign="top">Sorry, but this doesn''t do much for me.  The lighting is too harsh on the left side of the emblum, and I think I can even see you in the reflection.  It might be just me, but the subject doesn''t look completely straight.<br/> <br/>In my opinion, if you''re going to do such a simple photograph, it really has to be perfect technically.<br/>3</td>', 'Sorry, but this doesn''t do much for me.  The lighting is too harsh on the left side of the emblum, and I think I can even see you in the reflection.  It might be just me, but the subject doesn''t look completely straight. In my opinion, if you''re going to do such a simple photograph, it really has to be perfect technically.3', '2008-02-07 10:14:17.000000', NULL, 1),
(4467895, 642549, 89431, '<td valign="top">You probally shouldn''t have mixed the logos I''m not really sure what your advertising here, to me it just looks like you came home from shopping and spread all your new stuff out on your bed. And it''s just a touch blurry.</td>', 'You probally shouldn''t have mixed the logos I''m not really sure what your advertising here, to me it just looks like you came home from shopping and spread all your new stuff out on your bed. And it''s just a touch blurry.', '2008-02-07 10:14:30.000000', NULL, 1),
