(4469323, 642819, 24550, '<td valign="top">wonderfully clear and sharp.</td>', 'wonderfully clear and sharp.', '2008-02-07 20:17:32.000000', NULL, 1),
(4469328, 643143, 33672, '<td valign="top">Nice display of product and comp would work well for text placement. Background is appropriate but could use a bluer sky to give it more of a "refreshing'' look and feel.</td>', 'Nice display of product and comp would work well for text placement. Background is appropriate but could use a bluer sky to give it more of a "refreshing'' look and feel.', '2008-02-07 20:18:18.000000', NULL, 1),
(4469333, 642997, 33672, '<td valign="top">heh heh heh.... great idea and I know from experience that it still sells. However the light seems a bit dark and the ad needs more of an emphasis on the product to sell it better.</td>', 'heh heh heh.... great idea and I know from experience that it still sells. However the light seems a bit dark and the ad needs more of an emphasis on the product to sell it better.', '2008-02-07 20:20:03.000000', NULL, 1),
