INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4471504, 642615, 89423, '<td valign="top">The ring kind of looks awkword on a shell</td>', 'The ring kind of looks awkword on a shell', '2008-02-08 16:08:22.000000', NULL, 1),
(4471684, 642444, 88926, '<td valign="top">This needs back lighting to wake up the glass. The beer should stand out, see the bubbles in it, and condensation on the outside. Keep only one open can in the shot.</td>', 'This needs back lighting to wake up the glass. The beer should stand out, see the bubbles in it, and condensation on the outside. Keep only one open can in the shot.', '2008-02-08 18:03:13.000000', NULL, 1),
(4471702, 642962, 61961, '<td valign="top">A fun challenge to vote on, for a change, and largely due to creativity like this.  10 and good luck to you.</td>', 'A fun challenge to vote on, for a change, and largely due to creativity like this.  10 and good luck to you.', '2008-02-08 18:14:22.000000', NULL, 1),
(4471712, 641963, 56109, '<td valign="top">To be honest I would have like to see more of the sax in this photo. I''m not feeling the tight crop here. I think the clarity and sharpness are excellent, but not my taste overall.</td>', 'To be honest I would have like to see more of the sax in this photo. I''m not feeling the tight crop here. I think the clarity and sharpness are excellent, but not my taste overall.', '2008-02-08 18:17:16.000000', NULL, 1),
(4471714, 641468, 56109, '<td valign="top">Good idea, but I think the photo is a little bland. Could use a bit more color and "pop".</td>', 'Good idea, but I think the photo is a little bland. Could use a bit more color and "pop".', '2008-02-08 18:17:57.000000', NULL, 1),
(4471716, 641334, 56109, '<td valign="top">I find the background and the glare on the can to be quite distracting. When advertising a product, at a minimum, you want to be able to read the name of the product nice and clear. Good idea though.</td>', 'I find the background and the glare on the can to be quite distracting. When advertising a product, at a minimum, you want to be able to read the name of the product nice and clear. Good idea though.', '2008-02-08 18:19:59.000000', NULL, 1),
(4471717, 643188, 56109, '<td valign="top">I think a tighter crop would have worked better here.</td>', 'I think a tighter crop would have worked better here.', '2008-02-08 18:20:36.000000', NULL, 1),
(4471719, 643167, 55892, '<td valign="top">Just too perfect!</td>', 'Just too perfect!', '2008-02-08 18:21:34.000000', NULL, 1),
(4471724, 642521, 56109, '<td valign="top">To be honest, because watches are advertised in almost every magazine, the image has to really stand out above the other watch competitors.  I think the clarity of the pic is good, but this doesn''t scream out "BUY ME, heres what I have that they don''t" like I think a watch advertisement should should. A suggestion: when photographing an item for an advertisement, make sure the product name is visible and can be read (set the watch to a different time).</td>', 'To be honest, because watches are advertised in almost every magazine, the image has to really stand out above the other watch competitors.  I think the clarity of the pic is good, but this doesn''t scream out "BUY ME, heres what I have that they don''t" like I think a watch advertisement should should. A suggestion: when photographing an item for an advertisement, make sure the product name is visible and can be read (set the watch to a different time).', '2008-02-08 18:25:34.000000', NULL, 1),
(4471726, 642567, 56109, '<td valign="top">Damn, those look delicious. Nicely done.</td>', 'Damn, those look delicious. Nicely done.', '2008-02-08 18:26:17.000000', NULL, 1),
(4471729, 641639, 56109, '<td valign="top">Thanks for the laugh.</td>', 'Thanks for the laugh.', '2008-02-08 18:27:39.000000', NULL, 1),
(4471732, 640379, 56109, '<td valign="top">This is like an anti-advertisement I suppose. Good pic though.</td>', 'This is like an anti-advertisement I suppose. Good pic though.', '2008-02-08 18:28:43.000000', NULL, 1),
(4471740, 642950, 56109, '<td valign="top">Oh no, not Peeps!</td>', 'Oh no, not Peeps!', '2008-02-08 18:31:52.000000', NULL, 1),
(4471743, 642819, 56109, '<td valign="top">Because this is an advertisement challenge, I would have liked to see a brand name teabag or something. It''s a great shot, I just think it''s not as an effective advertisement as it could be with a product in the shot.</td>', 'Because this is an advertisement challenge, I would have liked to see a brand name teabag or something. It''s a great shot, I just think it''s not as an effective advertisement as it could be with a product in the shot.', '2008-02-08 18:34:24.000000', NULL, 1),
(4471750, 642570, 55892, '<td valign="top">great color, but the reflections spoiled the quality.  (Don''t you just hate it when that happens?  I always do)</td>', 'great color, but the reflections spoiled the quality.  (Don''t you just hate it when that happens?  I always do)', '2008-02-08 18:37:11.000000', NULL, 1),
(4471758, 642537, 55892, '<td valign="top">I like it!  Point of view is dramatic; hope it''s not from a fallen pedestrian!  Effective in b&amp;w.</td>', 'I like it!  Point of view is dramatic; hope it''s not from a fallen pedestrian!  Effective in b&w.', '2008-02-08 18:39:29.000000', NULL, 1),
(4471760, 642570, 56109, '<td valign="top">The glare is distracting and it seems a bit out of focus. Good idea that needs work.</td>', 'The glare is distracting and it seems a bit out of focus. Good idea that needs work.', '2008-02-08 18:40:14.000000', NULL, 1),
(4471763, 642719, 55892, '<td valign="top">get the whipped cream ready!</td>', 'get the whipped cream ready!', '2008-02-08 18:41:12.000000', NULL, 1),
(4471771, 643157, 56109, '<td valign="top">I like the shot, but I think a green background with the proper lighting would add a lot to this photo.</td>', 'I like the shot, but I think a green background with the proper lighting would add a lot to this photo.', '2008-02-08 18:44:31.000000', NULL, 1),
(4471772, 642412, 55892, '<td valign="top">Beautiful use of blues accentuating each other.</td>', 'Beautiful use of blues accentuating each other.', '2008-02-08 18:44:32.000000', NULL, 1),
(4471778, 642702, 55892, '<td valign="top">I like the reflection of the cat''s eyes on the glass, but the poor kitty is not focused well at all.</td>', 'I like the reflection of the cat''s eyes on the glass, but the poor kitty is not focused well at all.', '2008-02-08 18:47:21.000000', NULL, 1),
(4471779, 641615, 55892, '<td valign="top">cute!</td>', 'cute!', '2008-02-08 18:47:38.000000', NULL, 1),
