(4471942, 643065, 33672, '<td valign="top">I''m sure what the product is. Nice comp that allows for text placement. Lighting is nice and the bokeh draws you in.</td>', 'I''m sure what the product is. Nice comp that allows for text placement. Lighting is nice and the bokeh draws you in.', '2008-02-08 20:35:29.000000', NULL, 1),
(4472012, 641160, 80326, '<td valign="top">Good idea and well executed but the bottle is tilted, crop''s too tight and the background needs some cleaning up. Good effort though.</td>', 'Good idea and well executed but the bottle is tilted, crop''s too tight and the background needs some cleaning up. Good effort though.', '2008-02-08 21:30:41.000000', NULL, 1),
(4472069, 642835, 83313, '<td valign="top">Not sure exactly what this is (An egg cup?), but it looks cool and does make me want to go out and buy one.</td>', 'Not sure exactly what this is (An egg cup?), but it looks cool and does make me want to go out and buy one.', '2008-02-08 22:07:34.000000', NULL, 1),
(4472075, 643002, 83313, '<td valign="top">Nice scene, but I''ll have to cry shoehorn on this one. Your file size indicates more JPEG compression than you needed to use. Check your settings to come in just under the limit and avoid losing detail to compression.</td>', 'Nice scene, but I''ll have to cry shoehorn on this one. Your file size indicates more JPEG compression than you needed to use. Check your settings to come in just under the limit and avoid losing detail to compression.', '2008-02-08 22:10:08.000000', NULL, 1),
(4472078, 642958, 83313, '<td valign="top">A bit on the dark side. Though this is good, I don''t think it stands out like it should for such a subject.</td>', 'A bit on the dark side. Though this is good, I don''t think it stands out like it should for such a subject.', '2008-02-08 22:11:21.000000', NULL, 1),
(4472080, 642962, 90074, '<td valign="top">I just can''t belive this, it''s just so amazing. I love this.</td>', 'I just can''t belive this, it''s just so amazing. I love this.', '2008-02-08 22:12:50.000000', NULL, 1),
(4472085, 642834, 83313, '<td valign="top">I assume this is an actual trademarked product and that is why you''ve covered it up in the image and title? Well done. Only minor issue is some iso noise visible mostly in the background, but also on the lipstick. Composition is good and lighting is great.</td>', 'I assume this is an actual trademarked product and that is why you''ve covered it up in the image and title? Well done. Only minor issue is some iso noise visible mostly in the background, but also on the lipstick. Composition is good and lighting is great.', '2008-02-08 22:15:33.000000', NULL, 1),
(4472088, 642537, 83313, '<td valign="top">The bumpers are slightly clipped by the edge of the frame, so it seems a touch awkward. The background is a little bright and distracting from the car itself. I like the perspective view, the b/w tones and contrast on the car are done well.</td>', 'The bumpers are slightly clipped by the edge of the frame, so it seems a touch awkward. The background is a little bright and distracting from the car itself. I like the perspective view, the b/w tones and contrast on the car are done well.', '2008-02-08 22:17:38.000000', NULL, 1),
(4472092, 642940, 83313, '<td valign="top">Nicely done photo. Definitely one that I can see in a magazine ad. I alway thought that "Armitron" was a slightly weird brand name. You wear it on your arm, so they call it that, I suppose it makes sense.</td>', 'Nicely done photo. Definitely one that I can see in a magazine ad. I alway thought that "Armitron" was a slightly weird brand name. You wear it on your arm, so they call it that, I suppose it makes sense.', '2008-02-08 22:20:42.000000', NULL, 1),
(4472107, 642988, 90074, '<td valign="top">I like the dof, its so cool.</td>', 'I like the dof, its so cool.', '2008-02-08 22:33:55.000000', NULL, 1),
(4472109, 641161, 51614, '<td valign="top">Love the picture and title! Very creative</td>', 'Love the picture and title! Very creative', '2008-02-08 22:36:15.000000', NULL, 1),
(4472110, 642278, 51614, '<td valign="top">Excellent shot!</td>', 'Excellent shot!', '2008-02-08 22:36:21.000000', NULL, 1),
(4472111, 642444, 51614, '<td valign="top">I love everything about it</td>', 'I love everything about it', '2008-02-08 22:36:24.000000', NULL, 1),
