(4472190, 643093, 90068, '<td valign="top">888</td>', '888', '2008-02-08 23:39:39.000000', NULL, 1),
(4472285, 643173, 33672, '<td valign="top">You really capture the "fragile" feel with this. The symbolism is clear and the DOF sets up a nice comp. A nice ad photo.</td>', 'You really capture the "fragile" feel with this. The symbolism is clear and the DOF sets up a nice comp. A nice ad photo.', '2008-02-09 00:21:06.000000', NULL, 1),
(4472293, 642719, 33672, '<td valign="top">This ad has a nice comp that lends well to text placement. DOF really helps the comp too. My only pick is that the main product seems a bit dry. Perhaps you could''ve sprayed it with water or adjusted the red in PP to make it appear deeper.</td>', 'This ad has a nice comp that lends well to text placement. DOF really helps the comp too. My only pick is that the main product seems a bit dry. Perhaps you could''ve sprayed it with water or adjusted the red in PP to make it appear deeper.', '2008-02-09 00:24:20.000000', NULL, 1),
(4472300, 642996, 33672, '<td valign="top">Great layout. I''m sure what the product is and I like the way the guitar sits on an angle. If the "fender" ogo on the amp were more to the top left, text would find an easier placement into the ad.</td>', 'Great layout. I''m sure what the product is and I like the way the guitar sits on an angle. If the "fender" ogo on the amp were more to the top left, text would find an easier placement into the ad.', '2008-02-09 00:26:55.000000', NULL, 1),
(4472309, 642370, 33672, '<td valign="top">Nice tones and light. Really makes the wine feel rich. Focuus on the bottle is good but there''s some glare on the glass and the whole thing seems a bit tilted. A little more negative space on top would allow easier text placement.</td>', 'Nice tones and light. Really makes the wine feel rich. Focuus on the bottle is good but there''s some glare on the glass and the whole thing seems a bit tilted. A little more negative space on top would allow easier text placement.', '2008-02-09 00:29:46.000000', NULL, 1),
(4472315, 640379, 33672, '<td valign="top">Oh no.. The anti ad. Beautiful model, nice lighting and afunny message. However this type of ad usually backfires. A bit more negative space on top would give text a place.</td>', 'Oh no.. The anti ad. Beautiful model, nice lighting and afunny message. However this type of ad usually backfires. A bit more negative space on top would give text a place.', '2008-02-09 00:31:51.000000', NULL, 1),
