(4474370, 641651, 89940, '<td valign="top">Great color. Would like it a little more if the focus was a little closer so the Start button was in focus as opposed to the numbers.</td>', 'Great color. Would like it a little more if the focus was a little closer so the Start button was in focus as opposed to the numbers.', '2008-02-10 01:52:55.000000', NULL, 1),
(4474371, 643137, 89940, '<td valign="top">Nice capture. Like the lighting and concept.</td>', 'Nice capture. Like the lighting and concept.', '2008-02-10 01:53:40.000000', NULL, 1),
