(4475067, 643156, 33672, '<td valign="top">I see what your trying here. Perhaps a bit more contrast and a tighter view would display what''s being sold a little better.</td>', 'I see what your trying here. Perhaps a bit more contrast and a tighter view would display what''s being sold a little better.', '2008-02-10 11:22:16.000000', NULL, 1),
(4475075, 642566, 33672, '<td valign="top">this is a nice ad.Product is well displayed and place well within the comp to let text flow easily. The only pick I have is the glare from the wrapper. This might be fixed in a light tent I think. Otherwise excellent job.</td>', 'this is a nice ad.Product is well displayed and place well within the comp to let text flow easily. The only pick I have is the glare from the wrapper. This might be fixed in a light tent I think. Otherwise excellent job.', '2008-02-10 11:26:01.000000', NULL, 1),
