(4475257, 641160, 33732, '<td valign="top">Action is nice.</td>', 'Action is nice.', '2008-02-10 13:09:05.000000', NULL, 1),
(4475259, 642569, 33732, '<td valign="top">If only.  The complete engine would have been nice.<br/>Not so much sky would help.</td>', 'If only.  The complete engine would have been nice.Not so much sky would help.', '2008-02-10 13:10:34.000000', NULL, 1),
