INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4481936, 642962, 64929, '<td valign="top">Congrats!!!  One of my favs of the challenge for sure!!!</td>', 'Congrats!!!  One of my favs of the challenge for sure!!!', '2008-02-13 00:05:52.000000', NULL, 0),
(4481941, 642962, 41337, '<td valign="top">Wow. What a score! Congrats!</td>', 'Wow. What a score! Congrats!', '2008-02-13 00:06:58.000000', NULL, 0),
